     1	//! C `atoi` semantics.
     2	//!
     3	//! `std::atoi(s)` is specified as `(int)strtol(s, nullptr, 10)` with undefined
     4	//! behaviour on overflow. glibc's `strtol` saturates at `LONG_MAX`/`LONG_MIN`
     5	//! and the narrowing cast to `int` keeps the low 32 bits, which is what the
     6	//! reference binary does; we reproduce that exactly.
     7	
     8	/// Parse a string the way C's `atoi` does: skip leading whitespace, accept an
     9	/// optional sign, consume decimal digits, and stop at the first character that
    10	/// is not a digit. Anything unparseable yields `0`.
    11	pub fn atoi(s: &str) -> i32 {
    12	    let b = s.as_bytes();
    13	    let mut i = 0usize;
    14	
    15	    // isspace(): space, \t, \n, \v, \f, \r
    16	    while i < b.len() && (b[i] == b' ' || (0x09..=0x0d).contains(&b[i])) {
    17	        i += 1;
    18	    }
    19	
    20	    let mut negative = false;
    21	    if i < b.len() && (b[i] == b'+' || b[i] == b'-') {
    22	        negative = b[i] == b'-';
    23	        i += 1;
    24	    }
    25	
    26	    let mut acc: i64 = 0;
    27	    let mut overflowed = false;
    28	    while i < b.len() && b[i].is_ascii_digit() {
    29	        if !overflowed {
    30	            let digit = i64::from(b[i] - b'0');
    31	            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
    32	                Some(v) => acc = v,
    33	                None => overflowed = true,
    34	            }
    35	        }
    36	        i += 1;
    37	    }
    38	
    39	    let wide = if overflowed {
    40	        if negative {
    41	            i64::MIN
    42	        } else {
    43	            i64::MAX
    44	        }
    45	    } else if negative {
    46	        -acc
    47	    } else {
    48	        acc
    49	    };
    50	
    51	    wide as i32
    52	}
    53	
    54	#[cfg(test)]
    55	mod tests {
    56	    use super::atoi;
    57	
    58	    #[test]
    59	    fn matches_c_semantics() {
    60	        assert_eq!(atoi("19"), 19);
    61	        assert_eq!(atoi(""), 0);
    62	        assert_eq!(atoi("abc"), 0);
    63	        assert_eq!(atoi("12abc"), 12);
    64	        assert_eq!(atoi(" 5"), 5);
    65	        assert_eq!(atoi("+3"), 3);
    66	        assert_eq!(atoi("-5"), -5);
    67	        assert_eq!(atoi("3.9"), 3);
    68	        assert_eq!(atoi("0x5"), 0);
    69	        assert_eq!(atoi("007"), 7);
    70	        // glibc saturates to LONG_MAX, then truncates to int.
    71	        assert_eq!(atoi("999999999999999999999"), -1);
    72	    }
    73	}
