     1	//! Arena-backed node storage for the triangulator.
     2	//!
     3	//! The C++ original threads raw `Node*` pointers through every routine and
     4	//! relies on pointer identity for loop termination. We keep the same shape by
     5	//! storing nodes in a flat arena and using `usize` handles, with [`NULL`]
     6	//! standing in for `nullptr`.
     7	
     8	/// Sentinel handle standing in for C++'s `nullptr`.
     9	pub const NULL: usize = usize::MAX;
    10	
    11	/// A vertex in a circular doubly-linked polygon ring.
    12	#[derive(Clone, Debug)]
    13	pub struct Node {
    14	    /// Index of this vertex in the caller's flattened vertex list.
    15	    pub i: u32,
    16	    pub x: f64,
    17	    pub y: f64,
    18	
    19	    /// Previous / next vertex in the polygon ring.
    20	    pub prev: usize,
    21	    pub next: usize,
    22	
    23	    /// Z-order curve value.
    24	    pub z: i32,
    25	
    26	    /// Previous / next node in z-order.
    27	    pub prev_z: usize,
    28	    pub next_z: usize,
    29	
    30	    /// Whether this is a Steiner point.
    31	    pub steiner: bool,
    32	}
    33	
    34	/// Flat arena of [`Node`]s. Handles stay valid for the lifetime of a
    35	/// triangulation, which matters because the C++ code holds "pointers" across
    36	/// allocations of new nodes (`split_polygon`).
    37	#[derive(Default)]
    38	pub struct Arena {
    39	    nodes: Vec<Node>,
    40	}
    41	
    42	impl Arena {
    43	    pub fn new() -> Self {
    44	        Arena { nodes: Vec::new() }
    45	    }
    46	
    47	    pub fn reserve(&mut self, additional: usize) {
    48	        self.nodes.reserve(additional);
    49	    }
    50	
    51	    pub fn clear(&mut self) {
    52	        self.nodes.clear();
    53	    }
    54	
    55	    pub fn len(&self) -> usize {
    56	        self.nodes.len()
    57	    }
    58	
    59	    pub fn is_empty(&self) -> bool {
    60	        self.nodes.is_empty()
    61	    }
    62	
    63	    /// Equivalent of the C++ `nodes.construct(i, x, y)`.
    64	    pub fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
    65	        self.nodes.push(Node {
    66	            i,
    67	            x,
    68	            y,
    69	            prev: NULL,
    70	            next: NULL,
    71	            z: 0,
    72	            prev_z: NULL,
    73	            next_z: NULL,
    74	            steiner: false,
    75	        });
    76	        self.nodes.len() - 1
    77	    }
    78	}
