     1	//! Node-level geometric predicates — the C++ member functions that take
     2	//! `Node*` arguments.
     3	
     4	use super::geom::{area_xy, fmax, fmin, sign};
     5	use super::Earcut;
     6	
     7	impl Earcut {
     8	    /// Doubled signed area of the triangle `p q r`.
     9	    #[inline]
    10	    pub fn area(&self, p: usize, q: usize, r: usize) -> f64 {
    11	        let n = &self.nodes;
    12	        area_xy(n[p].x, n[p].y, n[q].x, n[q].y, n[r].x, n[r].y)
    13	    }
    14	
    15	    /// Exact coordinate equality (not an epsilon comparison — earcut relies on
    16	    /// bit equality here).
    17	    #[inline]
    18	    pub fn equals(&self, p1: usize, p2: usize) -> bool {
    19	        self.nodes[p1].x == self.nodes[p2].x && self.nodes[p1].y == self.nodes[p2].y
    20	    }
    21	
    22	    /// Do segments `p1q1` and `p2q2` intersect, including collinear touching?
    23	    pub fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
    24	        let o1 = sign(self.area(p1, q1, p2));
    25	        let o2 = sign(self.area(p1, q1, q2));
    26	        let o3 = sign(self.area(p2, q2, p1));
    27	        let o4 = sign(self.area(p2, q2, q1));
    28	
    29	        if o1 != o2 && o3 != o4 {
    30	            return true; // general case
    31	        }
    32	
    33	        // Collinear special cases.
    34	        if o1 == 0 && self.on_segment(p1, p2, q1) {
    35	            return true;
    36	        }
    37	        if o2 == 0 && self.on_segment(p1, q2, q1) {
    38	            return true;
    39	        }
    40	        if o3 == 0 && self.on_segment(p2, p1, q2) {
    41	            return true;
    42	        }
    43	        if o4 == 0 && self.on_segment(p2, q1, q2) {
    44	            return true;
    45	        }
    46	
    47	        false
    48	    }
    49	
    50	    /// For collinear `p`, `q`, `r`: does `q` lie within the bounding box of
    51	    /// segment `pr`?
    52	    pub fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
    53	        let n = &self.nodes;
    54	        n[q].x <= fmax(n[p].x, n[r].x)
    55	            && n[q].x >= fmin(n[p].x, n[r].x)
    56	            && n[q].y <= fmax(n[p].y, n[r].y)
    57	            && n[q].y >= fmin(n[p].y, n[r].y)
    58	    }
    59	
    60	    /// Does the diagonal `ab` cross any polygon edge?
    61	    pub fn intersects_polygon(&self, a: usize, b: usize) -> bool {
    62	        let mut p = a;
    63	        loop {
    64	            let pn = self.nodes[p].next;
    65	            if self.nodes[p].i != self.nodes[a].i
    66	                && self.nodes[pn].i != self.nodes[a].i
    67	                && self.nodes[p].i != self.nodes[b].i
    68	                && self.nodes[pn].i != self.nodes[b].i
    69	                && self.intersects(p, pn, a, b)
    70	            {
    71	                return true;
    72	            }
    73	            p = pn;
    74	            if p == a {
    75	                return false;
    76	            }
    77	        }
    78	    }
    79	
    80	    /// Does the diagonal `ab` lie inside the polygon's sector at `a`?
    81	    pub fn locally_inside(&self, a: usize, b: usize) -> bool {
    82	        let ap = self.nodes[a].prev;
    83	        let an = self.nodes[a].next;
    84	        if self.area(ap, a, an) < 0.0 {
    85	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
    86	        } else {
    87	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
    88	        }
    89	    }
    90	
    91	    /// Does the midpoint of `ab` fall inside the polygon? (Even-odd ray cast.)
    92	    pub fn middle_inside(&self, a: usize, b: usize) -> bool {
    93	        let mut inside = false;
    94	        let px = (self.nodes[a].x + self.nodes[b].x) / 2.0;
