 15	    /// Build a circular doubly-linked list from a ring, in the requested
 16	    /// winding order.
 17	    pub fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
 18	        let len = points.len();
 19	        let mut last = NULL;
 20	
 21	        // Original winding order of the ring (shoelace sum).
 22	        let mut sum = 0.0f64;
 23	        let mut j = if len > 0 { len - 1 } else { 0 };
 24	        for i in 0..len {
 25	            let p1 = points[i];
 26	            let p2 = points[j];
 27	            sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
 28	            j = i;
 29	        }
 30	
 31	        if clockwise == (sum > 0.0) {
 32	            for i in 0..len {
 33	                last = self.insert_node(self.vertices + i, points[i], last);
 34	            }
 35	        } else {
 36	            for i in (0..len).rev() {
 37	                last = self.insert_node(self.vertices + i, points[i], last);
 38	            }
 39	        }
 40	
 41	        if last != NULL {
 42	            let next = self.nodes[last].next;
 43	            if self.equals(last, next) {
 44	                self.remove_node(last);
 45	                last = next;
 46	            }
 47	        }
 48	
 49	        self.vertices += len;
 50	        last
 51	    }
