 57	        if last == NULL {
 58	            self.nodes[p].prev = p;
 59	            self.nodes[p].next = p;
 60	        } else {
 61	            let last_next = self.nodes[last].next;
 62	            self.nodes[p].next = last_next;
 63	            self.nodes[p].prev = last;
 64	            self.nodes[last_next].prev = p;
 65	            self.nodes[last].next = p;
